resource "aws_batch_job_definition" "<example_resource_name>" {
  name = "<example_resource_name>"
  type = "container"

  container_properties = jsonencode({
    image = "<image>"
    environment = [
      {
        name  = "DB_PASSWORD"
        value = var.db_password  # Use variable from Secrets Manager or SSM
      }
    ]
  })
}
